{"definitionId":"git-test-dml-approved-holiday-select","version":1,"categoryId":"im_accel_studio","definitionType":"sql","definitionName":"git-test 承認済み休暇日 SELECT","sortNumber":100,"definitionData":{"elementId":"im_queryExecutor","iconId":null,"elementProperties":{"query":"SELECT
  user_data."user_data_id" AS "user_data_id",
  user_data."user_cd" AS "user_cd",
  holiday."holiday_date" AS "holiday_date",
  user_data."holiday_class" AS "holiday_class",
  class_master."holiday_class_name" AS "holiday_class_name",
  user_data."holiday_color" AS "holiday_color",
  user_data."holiday_reason" AS "holiday_reason",
  holiday."holiday_date_id" AS "holiday_date_id",
  holiday."is_deleted" AS "is_deleted",
  holiday."delete_reason" AS "delete_reason"
FROM
  "gittest_user" AS user_data
INNER JOIN "gittest" AS holiday
  ON user_data."user_data_id" = holiday."user_data_id"
LEFT JOIN "gittest_master" AS class_master
  ON user_data."holiday_class" = class_master."holiday_class"
WHERE
  user_data."is_approved" = 1
  /*IF user_data_id != null*/
  AND user_data."user_data_id" = /*user_data_id*/''
  /*END*/
  /*IF holiday_date_id != null*/
  AND holiday."holiday_date_id" = /*holiday_date_id*/''
  /*END*/
  /*IF user_cd != null*/
  AND user_data."user_cd" = /*user_cd*/''
  /*END*/
  /*IF start_date != null*/
  AND holiday."holiday_date" >= /*start_date*/'2000-01-01'
  /*END*/
  /*IF end_date != null*/
  AND holiday."holiday_date" < /*end_date*/'2000-01-01'
  /*END*/
  /*IF include_deleted == null || !include_deleted*/
  AND holiday."is_deleted" = 0
  /*END*/
ORDER BY
  holiday."holiday_date" ASC
;
